esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    // params: target to call, value to forward, and arbitrary data
    function run(address target, uint value, bytes calldata data) public payable {
        // ensure this contract can send the requested value when calling c.sendMoney (if c needs balance, we may fund c via calling its fallback first)
        // We'll optionally fund c by calling its fallback via c.sendMoney with target = address(this) and value = 0 is not useful.
        // Instead, require this contract can send 'fund' to c if we choose to fund it here. Keep simple: require no precondition.
        require(true);

        // record before-values
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // perform the state-changing call on c as top-level statement and capture whether it reverted
        bool reverted;
        c.sendMoney(target, value, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-values
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // General rule: sendMoney does not change depositsCount; and either it reverted leaving balance same,
        // or it succeeded and reduced C's balance by exactly value (i.e., transferred value out)
        assert(
            afterDeposits == beforeDeposits &&
            (
                (reverted && afterBal == beforeBal) ||
                (!reverted && beforeBal >= value && afterBal + value == beforeBal)
            )
        );
    }

    // receive to accept Ether if target calls back into this contract
    receive() external payable { }
}

